//! The "scaffolded, not implemented" error channel for `com-amazonaws-ec2-amazonec2`.
//!
//! @generated by the emulator core scaffold op-stub generator.
//!
//! Every generated operation stub returns [`Scaffolded::not_implemented`], which the
//! framework renders as a protocol-correct **HTTP 501 `NotImplemented`**. Do not change
//! a stub to return a success value: a client, and any check that only asserts the call
//! succeeded, cannot tell an empty success from a real implementation. Implement the
//! operation, or leave the 501.
//!
//! ## The error type
//!
//! A stub's error type is `Scaffolded<{Op}ErrorModeled>` — the model's own error enum
//! plus the `NotImplemented` variant. Do not try to add `NotImplemented` to the
//! `#[operation_error]` enum directly; it accepts only variants the model declares.
//!
//! ## Implementing an operation
//!
//! Replace the `Err(..)` in the handler body with real behaviour. Each stub emits a
//! CONCRETE `impl From<{Op}ErrorModeled> for {Op}Error` beside its
//! alias, so `?` works through the wrapper and a modeled failure needs no ceremony:
//!
//! ```ignore
//! return Err(GetThingErrorModeled::ResourceNotFound(
//!     ResourceNotFound { message: Some("no such thing".into()) },
//! )
//! .into());
//! ```
//!
//! That impl is emitted per operation, not once for all of them — keep it that way if
//! you edit a stub.
//!
//! ## Once the operation is implemented
//!
//! Keep the `#[operation_error]` enum, the alias and the `From` impl.
//!
//! An implemented operation stops needing the 501, but the wrapper is also the only
//! place it can return an error its own model does not declare — `validation` above,
//! for a service whose model carries no client-input error. Delete the wrapper and the
//! handler has no way to refuse a bad request at all.

use aws_smithy_schema::serde::{SerdeError, SerializableStruct, ShapeSerializer};
use aws_smithy_schema::{Schema, ShapeId, ShapeType};
use smithy_server_runtime::OperationError;

/// The `message` member of the synthetic `NotImplemented` error shape.
///
/// `with_xml_name("Message")` matches the casing the restXml / awsQuery error
/// envelopes use, so the same value renders correctly on the XML protocols and as
/// lowercase `message` on the JSON/CBOR ones.
static NOT_IMPLEMENTED_MESSAGE: Schema = Schema::new_member(
    ShapeId::from_static(
        "smithy.framework#NotImplemented$message",
        "smithy.framework",
        "message",
    ),
    ShapeType::String,
    "message",
    0,
)
.with_xml_name("Message");

/// Schema for the synthetic `NotImplemented` error shape.
///
/// Deliberately in the `smithy.framework` namespace: this shape is NOT in any
/// service's model, so it must not collide with a modeled shape. The wire `__type` /
/// `<Code>` comes from [`OperationError::shape_name`] below, not from this schema.
pub static NOT_IMPLEMENTED_SCHEMA: Schema = Schema::new_struct(
    ShapeId::from_static(
        "smithy.framework#NotImplemented",
        "smithy.framework",
        "NotImplemented",
    ),
    ShapeType::Structure,
    &[&NOT_IMPLEMENTED_MESSAGE],
);

/// The payload of a `NotImplemented` failure: which operation was called, and the
/// fact that it is scaffolded rather than broken.
#[derive(Debug, Clone)]
pub struct NotImplemented {
    pub message: String,
}

impl NotImplemented {
    /// A `NotImplemented` naming `operation`.
    ///
    /// The wording matters: it must read as "not written yet", never as "the emulator
    /// is broken", because that distinction is what a human triaging a failing fixture
    /// needs first.
    pub fn new(operation: &str) -> Self {
        Self {
            message: format!(
                "operation {operation} is scaffolded but not implemented in this emulator"
            ),
        }
    }
}

impl std::fmt::Display for NotImplemented {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "NotImplemented: {}", self.message)
    }
}

impl std::error::Error for NotImplemented {}

impl SerializableStruct for NotImplemented {
    fn serialize_members(&self, s: &mut dyn ShapeSerializer) -> Result<(), SerdeError> {
        s.write_string(&NOT_IMPLEMENTED_MESSAGE, self.message.as_str())?;
        Ok(())
    }
}

/// The `message` member of the synthetic `ValidationException` error shape.
static VALIDATION_EXCEPTION_MESSAGE: Schema = Schema::new_member(
    ShapeId::from_static(
        "smithy.framework#ValidationException$message",
        "smithy.framework",
        "message",
    ),
    ShapeType::String,
    "message",
    0,
)
.with_xml_name("Message");

/// Schema for the synthetic `ValidationException` error shape.
///
/// In the `smithy.framework` namespace for the same reason as `NotImplemented`: the
/// shape is not in any service's model, so it must not collide with a modeled one.
/// If THIS service's model declares its own `ValidationException`, prefer that —
/// see [`Scaffolded::validation`].
pub static VALIDATION_EXCEPTION_SCHEMA: Schema = Schema::new_struct(
    ShapeId::from_static(
        "smithy.framework#ValidationException",
        "smithy.framework",
        "ValidationException",
    ),
    ShapeType::Structure,
    &[&VALIDATION_EXCEPTION_MESSAGE],
);

/// The payload of a `ValidationException`: why the request was refused.
#[derive(Debug, Clone)]
pub struct ValidationException {
    pub message: String,
}

impl ValidationException {
    /// A `ValidationException` carrying `message`.
    ///
    /// Say what was wrong with the request and name the member, the way the
    /// boundary validator does — the caller has to fix the request from this text
    /// alone.
    pub fn new(message: impl Into<String>) -> Self {
        Self {
            message: message.into(),
        }
    }
}

impl std::fmt::Display for ValidationException {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "ValidationException: {}", self.message)
    }
}

impl std::error::Error for ValidationException {}

impl SerializableStruct for ValidationException {
    fn serialize_members(&self, s: &mut dyn ShapeSerializer) -> Result<(), SerdeError> {
        s.write_string(&VALIDATION_EXCEPTION_MESSAGE, self.message.as_str())?;
        Ok(())
    }
}

/// The `message` member of the synthetic `ServiceError` error shape.
static SERVICE_ERROR_MESSAGE: Schema = Schema::new_member(
    ShapeId::from_static(
        "smithy.framework#ServiceError$message",
        "smithy.framework",
        "message",
    ),
    ShapeType::String,
    "message",
    0,
)
.with_xml_name("Message");

/// Schema for the synthetic `ServiceError` error shape.
///
/// In the `smithy.framework` namespace for the same reason as `NotImplemented`: the
/// shape is not in any service's model. Only the `Message` element comes from here —
/// the wire `<Code>` comes from the variant's own `code` (via
/// [`OperationError::shape_name`]), not from this schema's shape name.
pub static SERVICE_ERROR_SCHEMA: Schema = Schema::new_struct(
    ShapeId::from_static(
        "smithy.framework#ServiceError",
        "smithy.framework",
        "ServiceError",
    ),
    ShapeType::Structure,
    &[&SERVICE_ERROR_MESSAGE],
);

/// A failure this service answers with an error code of its own that its model
/// declares no shape for.
///
/// EC2's model declares ZERO error shapes — every operation's `errors` list is empty
/// (`smithy_query(query="operation",operation="<Op>")`) — while the real service
/// refuses requests with codes its clients branch on: `InvalidInstanceID.NotFound`
/// for an instance that does not exist, `IncorrectInstanceState` for a transition the
/// current state does not admit, `InvalidParameterValue` for a value it cannot
/// accept, `MissingParameter` for one the request left out,
/// `InvalidParameterCombination` for members that cannot hold together,
/// `DryRunOperation` for a `DryRun` request that would have succeeded. This
/// is how a handler answers with THAT code and status instead of flattening every
/// such refusal into `ValidationException`, which no EC2 client matches on, or into a
/// 501, which would claim the operation is unwritten. Reach it through one of the
/// named constructors below rather than inventing a code at the call site.
#[derive(Debug, Clone)]
pub struct ServiceError {
    /// The wire error code (`<Code>`). A `&'static str` so it can only be one of
    /// this service's known codes, never text taken from a request.
    pub code: &'static str,
    /// Why the request was refused. Says what was wrong and names the member or the
    /// resource, so the caller can fix the request from this text alone; built from
    /// the request, never from a recording.
    pub message: String,
    /// The HTTP status the real service answers this code with.
    pub status: u16,
}

impl std::fmt::Display for ServiceError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}: {}", self.code, self.message)
    }
}

impl std::error::Error for ServiceError {}

impl SerializableStruct for ServiceError {
    fn serialize_members(&self, s: &mut dyn ShapeSerializer) -> Result<(), SerdeError> {
        s.write_string(&SERVICE_ERROR_MESSAGE, self.message.as_str())?;
        Ok(())
    }
}

/// An operation's error channel: either the synthetic scaffold signal, or one of the
/// operation's own modeled errors.
#[derive(Debug)]
pub enum Scaffolded<E> {
    /// The operation is generated but has no implementation. Renders as HTTP 501.
    NotImplemented(NotImplemented),
    /// A modeled error the operation declares. Renders with the model's own status.
    Modeled(E),
    /// An error the service itself defines, which its model does not declare for this
    /// operation. Renders with the carried code and status.
    ServiceError(ServiceError),
    /// The request was refused as invalid. Renders as HTTP 400 with the error code
    /// `ValidationException`.
    ///
    /// On the JSON and CBOR protocols that is the same status and code the boundary
    /// validator answers with. Two differences are worth knowing, and neither is
    /// specific to this variant — every handler-returned error shares them:
    /// the awsJson families omit the `x-amzn-errortype` header that the boundary
    /// path sets, and the query protocols render a boundary refusal as
    /// `MalformedQueryString` rather than `ValidationException`, so a client
    /// matching on the error code there sees two codes for one logical failure.
    ValidationException(ValidationException),
}

impl<E> Scaffolded<E> {
    /// The scaffold signal for `operation`.
    pub fn not_implemented(operation: &str) -> Self {
        Self::NotImplemented(NotImplemented::new(operation))
    }

    /// Refuse the request as invalid, with HTTP 400 `ValidationException`.
    ///
    /// Reach for this when the request is wrong in a way the model cannot express,
    /// so the boundary validator passed it: a value outside a rule the service
    /// enforces but does not model, or a combination of members that cannot hold
    /// together. Answer it INSTEAD of `not_implemented` — a 501 says "nobody has
    /// written this yet", which is a different claim and is counted as one.
    ///
    /// If this service's model declares its own `ValidationException` (or another
    /// client-input error) use THAT: the modeled shape may carry members beyond
    /// `message` — a `reason`, a field list — and a real client reads them. When the
    /// operation already lists it, it is a plain variant on the generated error enum;
    /// `#[operation_error]`'s `extra_errors` is only for widening in a shape the
    /// SERVICE models that this OPERATION does not list.
    pub fn validation(message: impl Into<String>) -> Self {
        Self::ValidationException(ValidationException::new(message))
    }

    /// Refuse (or fail) the request with one of this service's own error codes.
    ///
    /// For a service whose model declares no error shapes — which, for EC2, is every
    /// error it has — this is the only way to answer the code and status the real
    /// service answers; see [`ServiceError`]. `code` is `&'static str` so the wire
    /// code is always one this service chose. Use one of the named constructors below
    /// rather than calling this with a fresh literal, so one code is worded one way
    /// across every operation.
    pub fn service_error(code: &'static str, status: u16, message: impl Into<String>) -> Self {
        Self::ServiceError(ServiceError {
            code,
            message: message.into(),
            status,
        })
    }

    /// `InvalidInstanceID.NotFound` (HTTP 400): the request named an instance id this
    /// account holds no instance for.
    pub fn invalid_instance_id_not_found(instance_id: &str) -> Self {
        Self::service_error(
            "InvalidInstanceID.NotFound",
            400,
            format!("The instance ID '{instance_id}' does not exist"),
        )
    }

    /// `InvalidInstanceID.Malformed` (HTTP 400): the request named something that is
    /// not an instance id at all, so there is nothing to look up.
    ///
    /// The message is [`crate::state::invalid_id_message`] — the one template this service
    /// words an unreadable resource id with, whatever kind of id it is.
    pub fn invalid_instance_id_malformed(instance_id: &str) -> Self {
        Self::service_error(
            "InvalidInstanceID.Malformed",
            400,
            crate::state::invalid_id_message(instance_id),
        )
    }

    /// `InvalidInstanceID.Malformed` (HTTP 400), in the wording of the operations whose own
    /// validator says an instance id "is malformed".
    ///
    /// The same code as [`Self::invalid_instance_id_malformed`] in a different wording, and
    /// a second named constructor rather than a literal at a call site so both wordings are
    /// visible here: EC2's per-operation validators do not agree about an unresolvable
    /// instance id, and the operations that answer this one say "The instance ID '<id>' is
    /// malformed" where the syntax check above says [`crate::state::invalid_id_message`].
    /// WHICH of the two
    /// an operation answers is a fact of that operation, recorded by its caller:
    ///
    /// * `crate::ops::create_replace_root_volume_task` refuses EVERY id it cannot resolve
    ///   as malformed, so it never reaches the not-found half at all;
    /// * `crate::ops::report_instance_status` DOES tell a value outside the id form from a
    ///   well-formed id that names nothing — it answers
    ///   [`Self::invalid_instance_id_not_found`] for the second — and words the first half
    ///   this way, which is what the recorded response for its malformed-id call carries.
    /// * `crate::ops::enable_instance_sql_ha_standby_detections` and
    ///   `crate::ops::disable_instance_sql_ha_standby_detections` draw the same distinction
    ///   and word the malformed half this way too, which is what their recorded refusals
    ///   carry — including under `DryRun`, which they answer AFTER this one.
    ///
    /// So an operation that draws the distinction and has no recorded wording of its own
    /// keeps using [`crate::state::require_known_instance`], which answers the constructor
    /// above for the malformed half.
    pub fn instance_id_is_malformed(instance_id: &str) -> Self {
        Self::service_error(
            "InvalidInstanceID.Malformed",
            400,
            format!("The instance ID '{instance_id}' is malformed"),
        )
    }

    /// `InvalidInstanceID.Malformed` (HTTP 400), in the wording of an operation whose
    /// validator refuses every instance id it could not read.
    ///
    /// A THIRD wording of this code beside the two above, and a named constructor rather
    /// than a literal at the call site for the same reason: which of the three an operation
    /// answers is a fact of that operation, recorded by its caller. EC2 ids reach the
    /// service obfuscated, and the operations that word this refusal report only that the
    /// id could not be read — the sentence is fixed, naming neither the value the request
    /// sent nor the form that was expected, which is the recorded answer
    /// `crate::ops::create_snapshots` gets for an instance id it cannot resolve.
    pub fn instance_id_could_not_be_unobfuscated() -> Self {
        Self::service_error("InvalidInstanceID.Malformed", 400, "Unable to unobfuscate ID.")
    }

    /// `InvalidID` (HTTP 400): the request named a resource id of a kind this
    /// operation cannot resolve at all.
    pub fn invalid_id(resource_id: &str) -> Self {
        Self::service_error(
            "InvalidID",
            400,
            format!("The ID '{resource_id}' is not valid"),
        )
    }

    /// `IncorrectInstanceState` (HTTP 400): the instance exists, but its current
    /// state does not admit the requested lifecycle transition.
    ///
    /// EC2 words this refusal as one sentence whose only interpolated value is the
    /// instance id the REQUEST named: it says which action the instance's state does not
    /// admit and stops there. It does NOT report the state the instance is actually in —
    /// a caller that wants it reads it back through a describe — so the state is not a
    /// parameter of this constructor, and the sentence ends in a full stop.
    pub fn incorrect_instance_state(instance_id: &str, action: &str) -> Self {
        Self::service_error(
            "IncorrectInstanceState",
            400,
            format!("The instance '{instance_id}' is not in a state from which it can be {action}."),
        )
    }

    /// `OperationNotPermitted` (HTTP 400): the request is well formed and the
    /// resource exists, but an attribute on it forbids the action.
    pub fn operation_not_permitted(message: impl Into<String>) -> Self {
        Self::service_error("OperationNotPermitted", 400, message)
    }

    /// `InvalidParameterValue` (HTTP 400): a parameter carries a value the service
    /// rejects.
    pub fn invalid_parameter_value(message: impl Into<String>) -> Self {
        Self::service_error("InvalidParameterValue", 400, message)
    }

    /// `InvalidParameterCombination` (HTTP 400): each parameter is valid alone, but
    /// they cannot be given together.
    pub fn invalid_parameter_combination(message: impl Into<String>) -> Self {
        Self::service_error("InvalidParameterCombination", 400, message)
    }

    /// `MissingParameter` (HTTP 400): a parameter the operation needs was not given.
    /// Distinct from a modelled `@required` member, which the boundary validator
    /// refuses before a handler runs.
    pub fn missing_parameter(message: impl Into<String>) -> Self {
        Self::service_error("MissingParameter", 400, message)
    }

    /// `TagLimitExceeded` (HTTP 400): the request would push a resource past the
    /// documented maximum number of tags.
    pub fn tag_limit_exceeded(message: impl Into<String>) -> Self {
        Self::service_error("TagLimitExceeded", 400, message)
    }

    /// `InstanceLimitExceeded` (HTTP 400): the launch would take the account past
    /// the number of instances it may run.
    pub fn instance_limit_exceeded(message: impl Into<String>) -> Self {
        Self::service_error("InstanceLimitExceeded", 400, message)
    }

    /// `InsufficientFreeAddressesInSubnet` (HTTP 400): no primary private address
    /// is left to give the instance.
    pub fn insufficient_free_addresses() -> Self {
        Self::service_error(
            "InsufficientFreeAddressesInSubnet",
            400,
            "The subnet does not have enough free private IPv4 addresses to \
             satisfy the request",
        )
    }

    /// `InvalidIPAddress.InUse` (HTTP 400): the address the request asked for is already
    /// held — a private address another resource has, or an Elastic IP address that still
    /// carries an association, which "you must disassociate … before you can release it"
    /// (`ReleaseAddress`).
    ///
    /// AWS's sentence for this class is `Address <address> is in use.`, the trailing period
    /// included, with the address taken from the request or from state.
    pub fn invalid_ip_address_in_use(address: &str) -> Self {
        Self::service_error(
            "InvalidIPAddress.InUse",
            400,
            format!("Address {address} is in use."),
        )
    }

    /// `UnsupportedHibernationConfiguration` (HTTP 400): the instance was not
    /// launched with hibernation enabled, so it cannot be hibernated.
    pub fn unsupported_hibernation_configuration(instance_id: &str) -> Self {
        Self::service_error(
            "UnsupportedHibernationConfiguration",
            400,
            format!("The instance '{instance_id}' was not launched with hibernation enabled"),
        )
    }

    /// `UnsupportedHibernationConfiguration` (HTTP 400): a launch asked to enable hibernation
    /// over a root device volume that would not be encrypted.
    ///
    /// "The root volume must be an encrypted Amazon EBS volume" is a prerequisite of
    /// hibernation (the EC2 User Guide's "Hibernate your Amazon EC2 instance"), so a launch
    /// that asks for it over an unencrypted root device is refused before anything is
    /// created. AWS's sentence for the class is fixed text that interpolates nothing from the
    /// request: a launch names no one volume for it to name.
    pub fn hibernation_requires_encrypted_root_volume() -> Self {
        Self::service_error(
            "UnsupportedHibernationConfiguration",
            400,
            "For hibernation, the root device volume must be encrypted.",
        )
    }

    /// `AuthFailure` (HTTP 400): the caller is not authorized for the resource the
    /// request names — an action the real service permits only to the OWNER of that
    /// resource, asked by an account that does not own it. Distinct from
    /// `UnauthorizedOperation`, which is about the caller's permission to call the
    /// operation at all.
    pub fn auth_failure(message: impl Into<String>) -> Self {
        Self::service_error(crate::state::AUTH_FAILURE, 400, message)
    }

    /// `DryRunOperation` (HTTP 412): `DryRun` was set and the request would
    /// otherwise have succeeded, so nothing was done.
    ///
    /// The code, the status and the sentence are [`crate::state`]'s, so a handler that
    /// answers the flag and the gate that answers it for an operation nobody has written
    /// ([`crate::service::dry_run`]) word one verdict one way.
    pub fn dry_run_operation() -> Self {
        Self::service_error(
            crate::state::DRY_RUN_OPERATION,
            crate::state::DRY_RUN_OPERATION_STATUS,
            crate::state::DRY_RUN_OPERATION_MESSAGE,
        )
    }

    /// `RequestLimitExceeded` (HTTP 503): the request asked for more work than the
    /// service will do in one call.
    pub fn request_limit_exceeded(message: impl Into<String>) -> Self {
        Self::service_error("RequestLimitExceeded", 503, message)
    }

    /// `InternalError` (HTTP 500): the service could not serve the request for a
    /// reason that is not the caller's fault.
    pub fn internal_error(message: impl Into<String>) -> Self {
        Self::service_error("InternalError", 500, message)
    }
}

impl<E: std::fmt::Display> std::fmt::Display for Scaffolded<E> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::NotImplemented(e) => write!(f, "{e}"),
            Self::Modeled(e) => write!(f, "{e}"),
            Self::ServiceError(e) => write!(f, "{e}"),
            Self::ValidationException(e) => write!(f, "{e}"),
        }
    }
}

/// `source()` forwards to the modeled error rather than taking the default `None`, so a
/// modeled error's own `source()` is preserved through the wrapper.
impl<E: std::error::Error + 'static> std::error::Error for Scaffolded<E> {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            Self::NotImplemented(e) => e.source(),
            Self::Modeled(e) => e.source(),
            Self::ServiceError(e) => e.source(),
            Self::ValidationException(e) => e.source(),
        }
    }
}

/// Every `OperationError` method delegates to the modeled error, so wrapping an
/// implemented operation's error channel changes NOTHING about how that error is
/// rendered. Only the synthetic variant behaves differently — and it is the one that
/// must answer 501.
impl<E: OperationError> OperationError for Scaffolded<E> {
    fn as_serializable(&self) -> &dyn SerializableStruct {
        match self {
            Self::NotImplemented(e) => e,
            Self::Modeled(e) => e.as_serializable(),
            Self::ServiceError(e) => e,
            Self::ValidationException(e) => e,
        }
    }

    fn variant_schema(&self) -> &'static Schema {
        match self {
            Self::NotImplemented(_) => &NOT_IMPLEMENTED_SCHEMA,
            Self::Modeled(e) => e.variant_schema(),
            Self::ServiceError(_) => &SERVICE_ERROR_SCHEMA,
            Self::ValidationException(_) => &VALIDATION_EXCEPTION_SCHEMA,
        }
    }

    /// The wire error code (`__type` on JSON/CBOR, `<Code>` on XML).
    ///
    /// Keep the literal as it is: changing it changes the wire error code clients match
    /// on. It is intentionally not tied to the Rust variant name.
    fn shape_name(&self) -> &'static str {
        match self {
            Self::NotImplemented(_) => "NotImplemented",
            Self::Modeled(e) => e.shape_name(),
            // The service's own code, carried on the variant.
            Self::ServiceError(e) => e.code,
            Self::ValidationException(_) => "ValidationException",
        }
    }

    /// 501 for the scaffold signal.
    ///
    /// Keep it 501 and not a 5xx server fault: SDK retry classifiers treat those as
    /// retryable, so a client would retry an operation that can never succeed.
    fn http_status(&self) -> u16 {
        match self {
            Self::NotImplemented(_) => 501,
            Self::Modeled(e) => e.http_status(),
            Self::ServiceError(e) => e.status,
            Self::ValidationException(_) => 400,
        }
    }

    fn query_error_code(&self) -> Option<&'static str> {
        match self {
            // No awsQuery code: the synthetic shape is not in the model, so there is
            // no `awsQueryError` trait to honour. The 501 + `<Code>NotImplemented`
            // envelope carries the signal on the query protocols too.
            Self::NotImplemented(_) => None,
            Self::Modeled(e) => e.query_error_code(),
            // The code on the variant is ALREADY the query wire code the service
            // answers with, and `shape_name` returns it, so there is nothing to
            // override here.
            Self::ServiceError(_) => None,
            // Same reason: the synthetic shape carries no `awsQueryError` trait.
            Self::ValidationException(_) => None,
        }
    }
}
